type Comment struct {
    ID        int64
    DiffID    string
    FilePath  string
    LineNo    int
    Author    string
    Body      string
    CreatedAt time.Time
}

// TopFiles 返回评论最多的前 N 个文件。
func TopFiles(ctx context.Context, comments []Comment, n int) []string {
    counts := make(map[string]int)
    for _, c := range comments {
        select {
        case <-ctx.Done():
            return nil
        default:
        }
        counts[c.FilePath]++
    }
    return takeTop(counts, n)
}

